/**
 * PostgreSQL / PGlite bootstrap DDL matching `packages/auth/src/schema.ts`
 * (the 11 standard tables generated by Better Auth CLI).
 * Kept co-located with `schema.ts` so `packages/db` does not duplicate Better Auth schema definitions.
 */
export const AUTH_DDL = `
CREATE TABLE IF NOT EXISTS "user" (
  id text PRIMARY KEY,
  name text NOT NULL,
  email text NOT NULL UNIQUE,
  email_verified boolean NOT NULL DEFAULT false,
  image text,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now(),
  role text,
  banned boolean DEFAULT false,
  ban_reason text,
  ban_expires timestamp,
  kind text NOT NULL DEFAULT 'HUMAN',
  bot_created_by_user_id text REFERENCES "user"(id) ON DELETE SET NULL,
  bot_disabled_at timestamp
);

CREATE TABLE IF NOT EXISTS "session" (
  id text PRIMARY KEY,
  expires_at timestamp NOT NULL,
  token text NOT NULL UNIQUE,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now(),
  ip_address text,
  user_agent text,
  user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  active_organization_id text,
  active_team_id text,
  impersonated_by text
);
CREATE INDEX IF NOT EXISTS "session_userId_idx" ON "session" (user_id);

CREATE TABLE IF NOT EXISTS "account" (
  id text PRIMARY KEY,
  account_id text NOT NULL,
  provider_id text NOT NULL,
  user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  access_token text,
  refresh_token text,
  id_token text,
  access_token_expires_at timestamp,
  refresh_token_expires_at timestamp,
  scope text,
  password text,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "account_userId_idx" ON "account" (user_id);

CREATE TABLE IF NOT EXISTS "verification" (
  id text PRIMARY KEY,
  identifier text NOT NULL,
  value text NOT NULL,
  expires_at timestamp NOT NULL,
  created_at timestamp NOT NULL DEFAULT now(),
  updated_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "verification_identifier_idx" ON "verification" (identifier);

CREATE TABLE IF NOT EXISTS "organization" (
  id text PRIMARY KEY,
  name text NOT NULL,
  slug text NOT NULL UNIQUE,
  logo text,
  created_at timestamp NOT NULL,
  metadata text
);

CREATE TABLE IF NOT EXISTS "team" (
  id text PRIMARY KEY,
  name text NOT NULL,
  member_count integer NOT NULL DEFAULT 0,
  organization_id text NOT NULL REFERENCES "organization"(id) ON DELETE CASCADE,
  created_at timestamp NOT NULL,
  updated_at timestamp
);
CREATE INDEX IF NOT EXISTS "team_organizationId_idx" ON "team" (organization_id);

CREATE TABLE IF NOT EXISTS "team_member" (
  id text PRIMARY KEY,
  team_id text NOT NULL REFERENCES "team"(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  membership_key text UNIQUE,
  created_at timestamp
);
CREATE INDEX IF NOT EXISTS "teamMember_teamId_idx" ON "team_member" (team_id);
CREATE INDEX IF NOT EXISTS "teamMember_userId_idx" ON "team_member" (user_id);

CREATE TABLE IF NOT EXISTS "member" (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES "organization"(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'member',
  created_at timestamp NOT NULL
);
CREATE INDEX IF NOT EXISTS "member_organizationId_idx" ON "member" (organization_id);
CREATE INDEX IF NOT EXISTS "member_userId_idx" ON "member" (user_id);

CREATE TABLE IF NOT EXISTS "invitation" (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES "organization"(id) ON DELETE CASCADE,
  email text NOT NULL,
  role text,
  team_id text,
  status text NOT NULL DEFAULT 'pending',
  expires_at timestamp NOT NULL,
  created_at timestamp NOT NULL DEFAULT now(),
  inviter_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "invitation_organizationId_idx" ON "invitation" (organization_id);
CREATE INDEX IF NOT EXISTS "invitation_email_idx" ON "invitation" (email);

CREATE TABLE IF NOT EXISTS "device_code" (
  id text PRIMARY KEY,
  device_code text NOT NULL,
  user_code text NOT NULL,
  user_id text,
  expires_at timestamp NOT NULL,
  status text NOT NULL,
  last_polled_at timestamp,
  polling_interval integer,
  client_id text,
  scope text
);
CREATE UNIQUE INDEX IF NOT EXISTS "deviceCode_deviceCode_uidx" ON "device_code" (device_code);
CREATE UNIQUE INDEX IF NOT EXISTS "deviceCode_userCode_uidx" ON "device_code" (user_code);

CREATE TABLE IF NOT EXISTS "apikey" (
  id text PRIMARY KEY,
  config_id text NOT NULL DEFAULT 'default',
  name text,
  start text,
  reference_id text NOT NULL,
  prefix text,
  key text NOT NULL,
  refill_interval integer,
  refill_amount integer,
  last_refill_at timestamp,
  enabled boolean DEFAULT true,
  rate_limit_enabled boolean DEFAULT true,
  rate_limit_time_window integer DEFAULT 86400000,
  rate_limit_max integer DEFAULT 10,
  request_count integer DEFAULT 0,
  remaining integer,
  last_request timestamp,
  expires_at timestamp,
  created_at timestamp NOT NULL,
  updated_at timestamp NOT NULL,
  permissions text,
  metadata text
);
CREATE INDEX IF NOT EXISTS "apikey_configId_idx" ON "apikey" (config_id);
CREATE INDEX IF NOT EXISTS "apikey_referenceId_idx" ON "apikey" (reference_id);
CREATE INDEX IF NOT EXISTS "apikey_key_idx" ON "apikey" (key);
`;
